L)) OR ((owner_user_id IS NULL) AND (owner_subject_id IS NOT NULL))))"},{"table":"service_record_corrections","name":"service_record_corrections_details_check","type":"c","definition":"CHECK (((length(btrim(details)) >= 1) AND (length(btrim(details)) <= 6000)))"},{"table":"service_record_corrections","name":"service_record_corrections_original_event_hash_check","type":"c","definition":"CHECK ((original_event_hash ~ '^[a-f0-9]{64}$'::text))"},{"table":"service_record_corrections","name":"service_record_corrections_owner_subject_id_fkey","type":"f","definition":"FOREIGN KEY (owner_subject_id) REFERENCES account_deletion_service_subjects(subject_id)"},{"table":"service_record_corrections","name":"service_record_corrections_owner_user_id_fkey","type":"f","definition":"FOREIGN KEY (owner_user_id) REFERENCES auth.users(id)"},{"table":"service_record_corrections","name":"service_record_corrections_pkey","type":"p","definition":"PRIMARY KEY (id)"},{"table":"service_record_corrections","name":"service_record_corrections_provider_subject_id_fkey","type":"f","definition":"FOREIGN KEY (provider_subject_id) REFERENCES account_deletion_service_subjects(subject_id)"},{"table":"service_record_corrections","name":"service_record_corrections_provider_user_id_fkey","type":"f","definition":"FOREIGN KEY (provider_user_id) REFERENCES auth.users(id)"},{"table":"service_record_corrections","name":"service_record_corrections_revision_check","type":"c","definition":"CHECK ((revision > 0))"}],"serviceCorrectionIndexes":[{"table":"service_correction_cleanup_authorizations","name":"service_correction_cleanup_authorizations_pkey","unique":true,"definition":"CREATE UNIQUE INDEX service_correction_cleanup_authorizations_pkey ON public.service_correction_cleanup_authorizations USING btree (transaction_id, target_table, row_id)"},{"table":"service_record_correction_decisions","name":"service_record_correction_decisions_correction_id_key","unique":true,"definition":"CREATE UNIQUE INDEX service_record_correction_decisions_correction_id_key ON public.service_record_correction_decisions USING btree (correction_id)"},{"table":"service_record_correction_decisions","name":"service_record_correction_decisions_pkey","unique":true,"definition":"CREATE UNIQUE INDEX service_record_correction_decisions_pkey ON public.service_record_correction_decisions USING btree (id)"},{"table":"service_record_corrections","name":"service_record_corrections_pkey","unique":true,"definition":"CREATE UNIQUE INDEX service_record_corrections_pkey ON public.service_record_corrections USING btree (id)"},{"table":"service_record_corrections","name":"service_record_corrections_submission","unique":false,"definition":"CREATE INDEX service_record_corrections_submission ON public.service_record_corrections USING btree (submission_id, revision DESC)"}],"serviceCorrectionIdentityInventory":[{"domain":"service","table_name":"service_record_correction_decisions","actor_column":"owner_user_id","subject_column":"owner_subject_id"},{"domain":"service","table_name":"service_record_corrections","actor_column":"owner_user_id","subject_column":"owner_subject_id"},{"domain":"service","table_name":"service_record_corrections","actor_column":"provider_user_id","subject_column":"provider_subject_id"}]}}$correction_delta$::jsonb;
table_guard constant text := $correction_table_guard$  -- Exact RPC-only correction tables; no API role or nonowner ACL/policy may expose them.
  for table_name in select jsonb_array_elements_text(manifest->'serviceCorrectionTables') loop
    table_oid:=to_regclass('public.'||table_name);
    if table_oid is null or not exists(select 1 from pg_class where oid=table_oid and relkind='r' and relrowsecurity and not relforcerowsecurity) then flags:=jsonb_set(flags,'{private_tables}','false');end if;
    if table_oid is null then flags:=jsonb_set(flags,'{private_table_grants}','false');
    else
      foreach role_name in array array['anon','authenticated','service_role'] loop
        if has_table_privilege(role_name,table_oid,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') or has_any_column_privilege(role_name,table_oid,'SELECT,INSERT,UPDATE,REFERENCES') then flags:=jsonb_set(flags,'{private_table_grants}','false');end if;
      end loop;
      if exists(select 1 from pg_class c cross join lateral aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a where c.oid=table_oid and a.grantee<>c.relowner)
        or exists(select 1 from pg_attribute c join pg_class t on t.oid=c.attrelid cross join lateral aclexplode(c.attacl) a where c.attrelid=table_oid and c.attnum>0 and not c.attisdropped and a.grantee<>t.relowner) then flags:=jsonb_set(flags,'{private_table_grants}','false');end if;
    end if;
    if exists(select 1 from pg_policy where polrelid=table_oid) then flags:=jsonb_set(flags,'{server_only_policies}','false');end if;
    if (select count(*) from pg_attribute where attrelid=table_oid and attnum>0 and not attisdropped)<>(select count(*) from jsonb_array_elements(manifest->'columns') c where c->>'table'=table_name) then flags:=jsonb_set(flags,'{schema_columns}','false');end if;
  end loop;
$correction_table_guard$;
catalog_guard constant text := $correction_catalog_guard$  -- Correction-ledger constraints, defaults, indexes and deletion associations are exact.
  for item in select value from jsonb_array_elements(manifest->'serviceCorrectionConstraints') loop
    if not exists(select 1 from pg_constraint c where c.conrelid=to_regclass('public.'||(item->>'table')) and c.conname=item->>'name' and c.contype::text=item->>'type' and c.convalidated and not c.condeferrable and pg_get_constraintdef(c.oid)=item->>'definition') then flags:=jsonb_set(flags,'{receipt_constraints}','false');end if;
  end loop;
  for item in select value from jsonb_array_elements(manifest->'serviceCorrectionIndexes') loop
    if not exists(select 1 from pg_index i where i.indexrelid=to_regclass('public.'||(item->>'name')) and i.indrelid=to_regclass('public.'||(item->>'table')) and to_jsonb(i.indisunique)=item->'unique' and i.indisvalid and i.indisready and pg_get_indexdef(i.indexrelid)=item->>'definition') then flags:=jsonb_set(flags,'{receipt_constraints}','false');end if;
  end loop;
  for item in select value from jsonb_array_elements(manifest->'serviceCorrectionDefaults') loop
    if not exists(select 1 from pg_attribute a left join pg_attrdef d on d.adrelid=a.attrelid and d.adnum=a.attnum where a.attrelid=to_regclass('public.'||(item->>'table')) and a.attname=item->>'name' and not a.attisdropped and coalesce(to_jsonb(pg_get_expr(d.adbin,d.adrelid)),'null'::jsonb)=item->'expression') then flags:=jsonb_set(flags,'{schema_columns}','false');end if;
  end loop;
  for item in select value from jsonb_array_elements(manifest->'serviceCorrectionIdentityInventory') loop
    if not exists(select 1 from public.account_deletion_identity_inventory i where i.domain=item->>'domain' and i.table_name=item->>'table_name' and i.actor_column=item->>'actor_column' and i.subject_column=item->>'subject_column') then flags:=jsonb_set(flags,'{schema_columns}','false');end if;
  end loop;
  if (select count(*) from public.account_deletion_identity_inventory i where i.table_name in (select jsonb_array_elements_text(manifest->'serviceCorrectionTables')))<>jsonb_array_length(manifest->'serviceCorrectionIdentityInventory') then flags:=jsonb_set(flags,'{schema_columns}','false');end if;
$correction_catalog_guard$;
begin
 proc_oid:=to_regprocedure('public.qrguitar_release_readiness()');
 if proc_oid is null then raise exception 'Missing readiness predecessor.';end if;
 select pg_get_functiondef(oid),prosrc into definition,source from pg_proc where oid=proc_oid;
 if encode(sha256(convert_to(replace(source,E'\r\n',E'\n'),'UTF8')),'hex') is distinct from '88edcb73987bf6c905cbd8670d6ccfff56cae63f32f39ff88a04a3193afc937d' or not exists(select 1 from pg_proc where oid=proc_oid and prosecdef and provolatile='s' and prorettype='jsonb'::regtype and proconfig=array['search_path=pg_catalog, public']::text[] and pg_get_userbyid(proowner) not in('anon','authenticated','service_role')) then raise exception 'Unsupported service-corrections readiness predecessor.';end if;
 if array_length(string_to_array(source,'$manifest$'),1)<>3 then raise exception 'Exact readiness manifest token required.';end if;
 old_token:='$manifest$'||split_part(source,'$manifest$',2)||'$manifest$';
 manifest:=split_part(source,'$manifest$',2)::jsonb;
 if manifest->>'releaseVersion' is distinct from '2026-10-05.3' or jsonb_array_length(manifest->'checks')<>14 then raise exception 'Unsupported readiness manifest predecessor.';end if;
 for item in select value from jsonb_array_elements(delta->'replaceFingerprints') loop
  if (select count(*) from jsonb_array_elements(manifest->'fingerprints') f where f->>'signature'=item->>'signature')<>1 then raise exception 'Exact predecessor function pin required.';end if;
  manifest:=jsonb_set(manifest,'{fingerprints}',(select jsonb_agg(case when f.value->>'signature'=item->>'signature' then item else f.value end order by f.ordinality) from jsonb_array_elements(manifest->'fingerprints') with ordinality f(value,ordinality)));
 end loop;
 for item_key,item_value in select key,value from jsonb_each(delta->'append') loop
  if jsonb_typeof(manifest->item_key) is distinct from 'array' then raise exception 'Exact readiness array required.';end if;
  manifest:=jsonb_set(manifest,array[item_key],(manifest->item_key)||item_value);
 end loop;
 manifest:=manifest||(delta->'set');
 next_token:='$manifest$'||manifest::text||'$manifest$';
 if (length(source)-length(replace(source,$table_anchor$  for table_name in select jsonb_array_elements_text(manifest->'tables') loop$table_anchor$,'')))/length($table_anchor$  for table_name in select jsonb_array_elements_text(manifest->'tables') loop$table_anchor$)<>1 or (length(source)-length(replace(source,$catalog_anchor$  for item in select value from jsonb_array_elements(manifest->'columns') loop$catalog_anchor$,'')))/length($catalog_anchor$  for item in select value from jsonb_array_elements(manifest->'columns') loop$catalog_anchor$)<>1 then raise exception 'Exact readiness guard anchors required.';end if;
 next_source:=replace(source,old_token,next_token);
 next_source:=replace(next_source,$table_anchor$  for table_name in select jsonb_array_elements_text(manifest->'tables') loop$table_anchor$,table_guard||$table_anchor$  for table_name in select jsonb_array_elements_text(manifest->'tables') loop$table_anchor$);
 next_source:=replace(next_source,$catalog_anchor$  for item in select value from jsonb_array_elements(manifest->'columns') loop$catalog_anchor$,catalog_guard||$catalog_anchor$  for item in select value from jsonb_array_elements(manifest->'columns') loop$catalog_anchor$);
 if replace(replace(replace(next_source,next_token,old_token),table_guard,''),catalog_guard,'') is distinct from source then raise exception 'Existing readiness guards changed.';end if;
 if (length(definition)-length(replace(definition,source,'')))/length(source)<>1 then raise exception 'Exact readiness function definition required.';end if;
 execute replace(definition,source,next_source);
 outcome:=public.qrguitar_release_readiness();
 if outcome->>'ready' is distinct from 'true' or outcome->>'releaseVersion' is distinct from '2026-10-05.4' or jsonb_array_length(outcome->'checks')<>14 or exists(select 1 from jsonb_array_elements(outcome->'checks') c where c->>'ok' is distinct from 'true') then raise exception 'Corrected service catalog is not release-ready.';end if;
end
$service_corrections_readiness$;
notify pgrst,'reload schema';
commit;
